-- Keep each Lua session's random state independent of the HTTP handler thread.
-- Windows xLua's math.random uses thread-local C state; consecutive requests
-- otherwise restart its sequence and repeatedly choose the minimum target count.
local randomState=1
local function nextRandom()
 -- Force floating-point arithmetic: Fengari's Lua integers are 32-bit.
 randomState=(randomState*1664525.0+1013904223.0)%4294967296.0
 return randomState/4294967296.0
end
