local function detach(n)
 if not n.parent then return end
 for i,v in ipairs(n.parent.children) do if v==n then table.remove(n.parent.children,i);break end end
 n.parent=nil
end
local function parent(n,p)
 detach(n);n.parent=p;if p then p.children[#p.children+1]=n end
end
