  SetSiblingIndex=function(_,ix)local p=n.parent;if p then detach(n);n.parent=p;table.insert(p.children,math.min(ix+1,#p.children+1),n) end end,
  GetChild=function(_,ix)return n.children[ix+1].transform end},
