 LoadImg=function(n,path,nativeSize,cb)
  local name=path:match('([^/]+)%.png$')
  local image=SPEC.images[name]
  assert(image,'unresolved UI Sprite: '..path)
  n.image=image
  local meta=SPEC.imageMetadata and SPEC.imageMetadata[image]
  if nativeSize~=false then
   assert(meta,'missing UI Sprite metadata: '..path)
   -- Image.SetNativeSize collapses the stretch anchors and uses sprite units.
   n.rect.m_AnchorMax=copy(n.rect.m_AnchorMin)
   local ppu=(meta.ppu or 100)/100
   n.rect.m_SizeDelta={x=meta.width/ppu,y=meta.height/ppu}
  end
  if cb then cb(n)end
 end,
 RandomInt=function(a,b)return a+math.floor(nextRandom()*(b-a+1))end,
