instantiate=function(template,p)
 local mapping={}
 local function clone(id)
  local d=SPEC.nodes[id];assert(d,'missing UI node '..id)
  local n=newNode(d);mapping[id]=n
  for _,child in ipairs(d.children or {})do parent(clone(child),n)end
  return n
 end
 local root=clone(assert(SPEC.templates[template],'missing UI template '..template))
 parent(root,p);if not p then roots[#roots+1]=root end
 if syncActivity then syncActivity()end
 for _,n in pairs(mapping)do
  if n.spec.lua then
   local env=setmetatable({gameObject=n},{__index=_G});env.this=env;n.lua=env
   for _,b in pairs(mapping)do if b.spec.binding then env[b.spec.binding]=b end end
   assert(load(assert(SOURCES[n.spec.lua],'missing Lua '..n.spec.lua),n.spec.lua,'t',env))()
   instances[#instances+1]={node=n,env=env}
   for _,b in pairs(mapping)do if b.spec.click then b.handler=env end end
   if env.Awake then env.Awake() end
  end
 end
 return root
end
